/// <summary>
/// CB624_TMSEngineSOCreation
/// Class to proceede with the creation/cancellation process for TMS engine
/// </summary>
internal class METTMSEngineSalesOrderProccess
{
    TMSCarrierCode      carrierCode;
    InventLocationId    inventLocationId;
    SalesTable          salesTable;
    MetSplitGroupTable  splitGroupTable;
    boolean             isSalesOrderPerishable;
    boolean             isToteCustomer;
    MetSalesTable       metSalesTable;
    TransDate           shippingDate;
    InventLocationId    shippingWhs;
    METTMSShipmentID    shipmentId;
    RecordInsertList    recordInsertList;
    METInventLocation   metInventLocation;
    InventParameters    inventParameters;
    METTobaccoRepackQty tobaccoRepackQtyFactor;
    METTobaccoRepackQty standardRepackQtyFactor;
    METWHSPalletVolume  whsPalletVolume;
    METWHSPalletVolume  whsToteVolume;
    METWHSPalletVolume  whsCaseVolume;
    METWHSPalletWeight  whsToteWeight;
    METWHSPalletWeight  whsPalletWeight;
    boolean             shipmentCreated;
    METTMSEngineSalesOrderProccessLinesTmp      proccessLinesTmp;
    TransDate                                   deliveryDate;

    const str  unitCSE = "@MET:CSE";
    const str  unitTOT = "@MET:TOT";
    const str  unitPal = "@MET:PAL";
    
    const METTMSCommodity   tobCommodity = "@MET:TOB";
    const str  unitEA = "@MET:EA";
    const   int tobaccoRepackQtyFactorDefault = 25;
    const   int standardRepackQtyFactorDefault = 45;

}

